SELECT v.title,v.slug,v.short_title,c.id,v.sub::sub_category_kind,v.listing::listing_kind,v.price,v.period,ci.id,v.area,v.state,v.size,v.sqm,v.beds,v.baths,v.parking,v.dock,v.height,v.floors,v.yr,v.img,v.gallery::jsonb,v.badges::jsonb,v.descr,v.features::jsonb,a.id,v.featured,v.hot,'Active',now()-(v.age_days||' days')::interval, v.title||' | Mai''Lafiya Homes', left(v.descr,155)
FROM v JOIN property_categories c ON c.slug=v.cat JOIN cities ci ON ci.slug=v.city JOIN agents a ON a.name=v.agent;
