INSERT INTO services (title,icon,blurb,sort_order) VALUES
('Warehouse Leasing','warehouse','Access our curated network of industrial-grade warehouses across Northern Nigeria — from 500 sqm SME units to 10,000+ sqm bonded facilities.',1),
('Warehouse Sales & Acquisition','keys','Buy-side and sell-side representation for industrial assets. Due diligence, title search, structural surveys, and negotiation handled end-to-end.',2),
('Facility Management','gear','We manage your industrial or commercial property: tenant relations, rent collection, maintenance, security, and quarterly financial reporting.',3),
('Property Valuation','search','Independent valuations for financing, insurance, portfolio reporting, and litigation — carried out by NIESV-registered professionals.',4),
('Site Sourcing & Advisory','map','Bespoke site searches for build-to-suit developments, logistics hubs, or manufacturing plants — including permits and zoning advisory.',5),
('Corporate Real Estate','shield','Office and retail space acquisition, lease negotiation, and portfolio rationalisation for corporate clients operating across the North.',6);
INSERT INTO promises (icon,title,description,sort_order) VALUES
('shield','Verified titles','Every property title search, C of O check, and encumbrance report done before listing.',1),
('clock','4-hour response','Enquiries answered within 4 working hours — every single one, no exceptions.',2),
('check','Personally walked','Our consultants inspect and photograph every property. What you see is what you get.',3),
('keys','Financing arranged','Bank partnerships and mortgage introductions for qualifying buyers.',4);
INSERT INTO "values" (title,description,sort_order) VALUES
('Amana (Trust)','We hold client funds, documents and confidences as a sacred trust — and we have never given anyone a reason to doubt it.',1),
('Adalci (Fairness)','Transparent fees, honest valuations, and the same straight answer whether the deal is ₦3 million or ₦3 billion.',2),
('Sabuntawa (Renewal)','We keep improving how we inspect, price and manage property so every client gets better service than the last.',3),
('Al''umma (Community)','Real estate is how families and businesses grow. We invest in the communities where we work across the North.',4);
