INSERT INTO testimonials_google (name,avatar,when_label,when_date,stars,body,featured,sort_order) VALUES
('Kelechi Okoro','assets/handshake-2.jpg','2 weeks ago',current_date-14,5,'Sourced a 4,000 sqm bonded warehouse for us in Kano within 6 weeks including customs paperwork. Ibrahim''s team is on another level — they know every dock and every landlord.',true,1),
('Fatima Aliyu','assets/handshake-1.jpg','1 month ago',current_date-35,5,'Third warehouse we''ve leased through Mai''Lafiya. Consistently transparent on fees and they understand what industrial operators actually need — power, floor loads, dock heights.',true,2),
('Ahmed Bello','assets/team-2.jpg','2 months ago',current_date-65,5,'Full management contract on my Kaduna portfolio. Rent collected on time, quarterly reports arrive without me asking. Best decision we made in 2024.',true,3),
('Sadiq Muhammed','assets/team-1.jpg','3 months ago',current_date-95,5,'Bought my family duplex in Maitama through them. Straightforward, no hidden charges, got financing lined up. Highly recommend for both commercial and residential.',true,4);
